const input = $json;
const source = input.qualification || input.qualification_patch || input.decision?.qualification_patch || {};
const clean = v => v == null ? null : String(v).trim();
const number = v => { if (v == null || v === '') return null; const direct = Number(v); if (Number.isFinite(direct)) return direct; const n = Number(String(v).replace(/[^0-9,.-]/g,'').replace(/\./g,'').replace(',','.')); return Number.isFinite(n) ? n : null; };
const regions = Array.isArray(source.regioes) ? source.regioes.map(clean).filter(Boolean) : (clean(source.regiao) ? [clean(source.regiao)] : []);
return [{json:{...input,search_filters:{transaction_type:'Aluguel',city:clean(source.cidade)||'Goiânia',regions,property_type:clean(source.tipo_imovel),min_area:number(source.area_minima),max_area:number(source.area_maxima),min_price:number(source.valor_minimo),max_price:number(source.valor_maximo),bedrooms:number(source.quartos),bathrooms:number(source.banheiros),parking:number(source.vagas),limit:5}}}];

const ctx = $('02 Preparar filtros').first().json;
const f = ctx.search_filters;
const norm=(v)=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const money=(v)=>v==null?'não informado':Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const typeMap={apartamento:['apartment','apartamento','flat'],casa:['house','casa','sobrado'],studio:['studio','kitnet','loft'],comercial:['commercial','comercial','sala','loja','shed_deposit_warehouse'],galpao:['shed_deposit_warehouse','galpao','galpao','warehouse','deposito'],deposito:['shed_deposit_warehouse','deposito','warehouse']};
const wantedType=norm(f.property_type);
const candidates=$input.all().map(i=>i.json).filter(p=>{
 const trans=norm(p.context_transaction_type||p.transaction_type);
 const price=Number(p.rental_price ?? p.price);
 if(trans && !trans.includes('alug')) return false;
 if(f.city && norm(p.city)!==norm(f.city)) return false;
 if(f.min_area!=null && (p.area==null || Number(p.area)<f.min_area)) return false;
 if(f.max_area!=null && (p.area==null || Number(p.area)>f.max_area)) return false;
 if(f.min_price!=null && price<f.min_price) return false;
 if(f.max_price!=null && price>f.max_price) return false;
 if(f.bedrooms!=null && Number(p.bedrooms||0)<f.bedrooms) return false;
 if(f.bathrooms!=null && Number(p.bathrooms||0)<f.bathrooms) return false;
 if(f.parking!=null && Number(p.parking||0)<f.parking) return false;
 if(wantedType){ const allowed=typeMap[wantedType]||[wantedType]; if(!allowed.some(t=>norm(p.property_type).includes(t)||norm(p.title).includes(t))) return false; }
 return true;
}).map(p=>{
 let score=0; const hay=norm([p.neighborhood,p.address,p.title].filter(Boolean).join(' '));
 const matchedRegions=f.regions.filter(r=>hay.includes(norm(r)));
 if(matchedRegions.length) score+=40;
 else if(f.regions.length) score-=25;
 if(f.max_price!=null){ const price=Number(p.rental_price??p.price); score+=Math.max(0,20-Math.abs(f.max_price-price)/Math.max(f.max_price,1)*20); }
 score+=Math.min(Number(p.bedrooms||0),5)*2;
 return {...p,_score:score,_matched_regions:matchedRegions};
}).filter(p=>!f.regions.length||p._matched_regions.length).sort((a,b)=>b._score-a._score||Number(a.rental_price??a.price)-Number(b.rental_price??b.price)).slice(0,f.limit);
return [{json:{session_id:ctx.session_id,contact_id:ctx.contact_id||null,phone:ctx.phone||null,batch_id:ctx.batch_id||null,filters:f,count:candidates.length,properties:candidates,money}}];

const data=$json;
const money=v=>v==null?'Valor sob consulta':Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
let reply;
if(!data.properties.length){const place=data.filters.regions?.length?'nessa região':'em '+(data.filters.city||'Goiânia');reply='No catálogo atual, não encontrei opções '+place+' com esses critérios. Quer que eu amplie a busca?'}
else {
 const list=data.properties.slice(0,3);
 const intro=list.length===1?'Achei esta opção para você:':'Achei estas opções para você:';
 const blocks=list.map((p,i)=>{
  const title=p.title||p.property_type||'Imóvel';
  const location=p.neighborhood||p.city||data.filters.city;
  const facts=[p.area!=null?Number(p.area)+' m²':null,money(p.rental_price??p.price)].filter(Boolean).join(' · ');
  return (i+1)+'. '+title+' — '+location+'\n'+facts+(p.url?'\n'+p.url:'');
 });
 reply=intro+'\n\n'+blocks.join('\n\n')+'\n\nAlgum imóvel te interessou? Se quiser visitar, me diga qual.';
}
return [{json:{...data,reply,action:'property_results',source:'buscaimoveis'}}];
